import { Table, StringColumn } from '../../db'

export const sys_security_type = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Type',
    name: 'sys_security_type',
    schema: {
        description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Description',
            maxLength: 4000,
        }),
        name: StringColumn({
            active: false,
            label: 'Name',
            mandatory: true,
            maxLength: 80,
            unique: true,
        }),
    },
    textIndex: true,
})
